INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(8891, 0, 0, 'You can''t hide from us.  Prepare to burn!', 14, 0, 100, 0, 0, 0, 'Anvilrage Guardsman'),
(8905, 0, 0, 'Intruders!!', 12, 0, 100, 0, 0, 0, 'Warbringer Construct'),
(8906, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Ragereaver Golem'),
(8929, 0, 0, '%s is visibly shaken by the death of Emperor Thaurissan.', 16, 0, 100, 18, 0, 0, 'Princess Moira Bronzebeard'),
(9016, 0, 0, '%s begins to summon a lava spawn!', 16, 0, 100, 0, 0, 0, 'Bael''Gar'),
(9017, 0, 0, 'I cannot be destroyed! By the will of Ragnaros, I shall be reborn!', 12, 0, 100, 0, 0, 0, 'Lord Incendius'),
(9021, 0, 0, 'Key... get the key... Gerstahn has... key.', 12, 0, 100, 0, 0, 0, 'Kharan Mighthammer'),
(9021, 0, 1, 'Try and make yourself useful, $r. GET ME OUT OF HERE! The High Interrogator has the key.', 12, 0, 100, 0, 0, 0, 'Kharan Mighthammer'),
(9021, 0, 2, 'HEY! HEY YOU! $R! Get me out of here!', 12, 0, 100, 0, 0, 0, 'Kharan Mighthammer'),
(9021, 0, 3, '%s groans.', 16, 0, 100, 0, 0, 0, 'Kharan Mighthammer'),
(9042, 0, 0, '%s becomes enraged!', 16, 0, 100, 0, 0, 0, 'Verek'),
(9499, 0, 0, 'Drink up!  There''s more where that came from!', 12, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 0, 1, 'Enjoy!  You won''t find better ale anywhere!', 12, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 0, 2, 'Have you tried the Dark Iron Ale?  It''s the best!', 12, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 0, 3, 'Try the boar!  It''s my new recipe!', 12, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 1, 0, 'What are you doing over there?', 14, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 1, 1, 'Hey!  Get away from that!', 14, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 1, 2, 'Hey!  Stop that!', 14, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 1, 3, 'No stealing the goods!', 14, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 1, 4, 'Phalanx, I think you need to teach thos person a lesson.', 14, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 2, 0, 'Hey, my pockets were picked!', 14, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 2, 1, 'That''s it!  No more beer until this mess is sorted out!', 14, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9499, 3, 0, 'That''s it!  You''re going down!', 14, 0, 100, 0, 0, 0, 'Plugger_Spazzring'),
(9500, 0, 0, 'You got it!', 12, 0, 100, 0, 0, 0, 'Nagmara'),
(9500, 0, 1, 'Coming right up!', 12, 0, 100, 0, 0, 0, 'Nagmara'),
(9500, 0, 2, 'I''ll bring it right over, baby...', 12, 0, 100, 0, 0, 0, 'Nagmara'),
(9500, 0, 3, 'Yes $gsir:madam;.', 12, 0, 100, 0, 0, 0, 'Mistress Nagmara'),
(9500, 1, 0, 'Hey, Rocknot!', 12, 0, 100, 0, 0, 0, 'Nagmara'),
(9500, 2, 0, 'Let''s go, honey.', 12, 0, 100, 0, 0, 0, 'Nagmara'),
(9500, 3, 0, '%s kisses her lover.', 12, 0, 100, 0, 0, 0, 'Nagmara'),
(9503, 1, 0, 'I want more ale!  Give me more ale!', 12, 0, 100, 0, 0, 0, 'Rocknot'),
(9503, 2, 0, 'That one''s empty!!', 12, 0, 100, 0, 0, 0, 'Rocknot'),
(9503, 3, 0, 'Ah, empty again!', 12, 0, 100, 0, 0, 0, 'Rocknot'),
(9503, 4, 0, 'ALE!', 12, 0, 100, 0, 0, 0, 'Rocknot'),
(9503, 5, 0, '%s kisses Mistress Nagmara', 12, 0, 100, 0, 0, 0, 'Rocknot'),
(9503, 6, 0, 'I''m getting out of here!', 12, 0, 100, 0, 0, 0, 'Rocknot'),
(9537, 0, 0, 'Get away from those kegs!', 14, 0, 100, 5, 0, 0, 'Hurley Blackbreath'),
(9537, 1, 0, 'You''ll pay for that!', 12, 0, 100, 5, 0, 0, 'Hurley Blackbreath'),
(9543, 0, 0, 'No!  Get away from me!  Help!!', 12, 0, 100, 0, 0, 0, 'Ribbly Screwspigot'),
(9545, 0, 0, 'Hey Nagmara!  How about a mug of Dark Iron Ale?', 12, 0, 100, 0, 0, 0, 'Patron'),
(9545, 0, 1, 'Nagmara!  Have any mutton left?', 12, 0, 100, 0, 0, 0, 'Patron'),
(9545, 0, 2, 'Mistress, you tell Plugger that I want more of his ale.  I can''t get enough!', 12, 0, 100, 0, 0, 0, 'Patron'),
(9545, 0, 3, 'Hey Nag, how about you slice me off a piece of that...', 12, 0, 100, 0, 0, 0, 'Patron'),
(9547, 0, 0, 'Hey Nagmara!  How about a mug of Dark Iron Ale?', 12, 0, 100, 0, 0, 0, 'Patron'),
(9547, 0, 1, 'Nagmara!  Have any mutton left?', 12, 0, 100, 0, 0, 0, 'Patron'),
(9547, 0, 2, 'Mistress, you tell Plugger that I want more of his ale.  I can''t get enough!', 12, 0, 100, 0, 0, 0, 'Patron'),
(9547, 0, 3, 'Hey Nag, how about you slice me off a piece of that...', 12, 0, 100, 0, 0, 0, 'Patron'),
(9554, 0, 0, 'Hey Nagmara!  How about a mug of Dark Iron Ale?', 12, 0, 100, 0, 0, 0, 'Patron'),
(9554, 0, 1, 'Nagmara!  Have any mutton left?', 12, 0, 100, 0, 0, 0, 'Patron'),
(9554, 0, 2, 'Mistress, you tell Plugger that I want more of his ale.  I can''t get enough!', 12, 0, 100, 0, 0, 0, 'Patron'),
(9554, 0, 3, 'Hey Nag, how about you slice me off a piece of that...', 12, 0, 100, 0, 0, 0, 'Patron'),
(23872, 0, 0, 'This is an insult! An affront! They deny us participation in time-honored dwarven traditions!', 12, 0, 100, 15, 0, 0, 'Coren Direbrew SAY_INTRO'),
(23872, 1, 0, 'Are we going to hide in our mountain and let those swill-peddlers have their little shindig without us?!', 12, 0, 100, 15, 0, 0, 'Coren Direbrew SAY_INTRO2'),
(23872, 2, 0, 'DAMN RIGHT! We''ll show ''em why you don''t cross the Dark Iron dwarves!', 12, 0, 100, 15, 0, 0, 'Coren Direbrew SAY_INTRO3'),
(23872, 3, 0, 'You''ll pay for this insult, $c!', 12, 0, 100, 15, 0, 0, 'Coren Direbrew SAY_INSULT');
